(function(){const form=document.querySelector('#access-form'),error=document.querySelector('#access-error'),button=form.querySelector('[type=submit]'),password=form.elements.password,params=new URL(location.href).searchParams,next=params.get('next')||'/login/';document.querySelector('.reveal-password').addEventListener('click',e=>{const b=e.currentTarget,visible=password.type==='password';password.type=visible?'text':'password';b.setAttribute('aria-label',visible?'Hide password':'Show password');b.setAttribute('aria-pressed',String(visible));});const nda=document.querySelector('#nda-dialog');document.querySelector('#nda-link').addEventListener('click',()=>nda.showModal());nda.querySelectorAll('.close-nda').forEach(b=>b.addEventListener('click',()=>nda.close()));form.addEventListener('submit',async e=>{e.preventDefault();button.disabled=true;error.textContent='';try{const response=await fetch('/api/access/login',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({password:password.value,remember:form.elements.remember.checked,next})}),data=await response.json();if(!response.ok)throw Error(data.error||'Please try again.');password.value='';button.querySelector('span').textContent='You’re in.';document.body.classList.add('leaving');setTimeout(()=>location.assign(data.next),250);}catch(err){error.textContent=err.message;button.disabled=false;}});fetch('/api/access/status',{credentials:'same-origin'}).then(r=>r.json()).then(data=>{if(!data.authenticated)return;let destination='/login/';try{const u=new URL(next,location.origin);if(u.origin===location.origin&&next.startsWith('/')&&!next.startsWith('//')&&!u.pathname.startsWith('/welcome'))destination=u.pathname+u.search+u.hash;}catch{}location.replace(destination);}).catch(()=>{});})();
